{
  "name": "llm-split",
  "version": "1.0.0",
  "description": "Hold your LLM traffic to a target split across two providers or plans — a daily ledger counts every call, and the next one routes to the under-target side.",
  "license": "MIT",
  "type": "commonjs",
  "scripts": {
    "test": "node examples/demo.cjs >/dev/null && echo ok",
    "check": "node --check lib/llm-split.cjs && node --check examples/demo.cjs && echo ok"
  },
  "keywords": [
    "llm",
    "routing",
    "load-balancer",
    "cost-optimization",
    "rate-plans",
    "ledger",
    "observability",
    "zero-dependencies"
  ],
  "engines": {
    "node": ">=18"
  },
  "dependencies": {},
  "devDependencies": {}
}

'use strict';
/**
 * llm-split.cjs — two-provider LLM volume balancer.
 *
 * Holds fleet traffic to a target split across two sides (default: metered, flat).
 * Daily ledger at data/ledger.json ({ "YYYY-MM-DD": { <sideA>: N, <sideB>: N } }, last 14
 * days kept, atomic writes). Instrument your client choke points with record(side) so EVERY
 * call is counted whatever the caller; pickSide() returns the UNDER-target side for the next
 * eligible call. Counts are approximate under concurrent writers (lock-free read-modify-write)
 * — the right tolerance for a balancer, the wrong tool for billing.
 *
 * Env: LLM_SPLIT=0 kill-switch (default on) · LLM_SPLIT_SIDES=metered,flat (A first, B second)
 *      LLM_SPLIT_TARGET=20 (min % share for side B) · LLM_SPLIT_DATA_DIR (ledger dir override)
 * CLI: node lib/llm-split.cjs  → live status JSON.
 */
const fs = require('fs');
const path = require('path');

const DATA_DIR = () => process.env.LLM_SPLIT_DATA_DIR || path.join(__dirname, '..', 'data');
const LEDGER = () => path.join(DATA_DIR(), 'ledger.json');
const KEEP_DAYS = 14;

function enabled() { return process.env.LLM_SPLIT !== '0'; }

/** The two side names — A first (metered/default), B second (flat-rate, target-protected). */
function sides() {
  const raw = String(process.env.LLM_SPLIT_SIDES || 'metered,flat').split(',').map((s) => s.trim()).filter(Boolean);
  return raw.length === 2 && raw[0] !== raw[1] ? raw : ['metered', 'flat'];
}

/** Minimum % share for side B. */
function target() {
  const n = Number(process.env.LLM_SPLIT_TARGET);
  return (Number.isFinite(n) && n > 0 && n < 100) ? n : 20;
}

function today() { return new Date().toISOString().slice(0, 10); }

function load() {
  try {
    const j = JSON.parse(fs.readFileSync(LEDGER(), 'utf8'));
    return (j && typeof j === 'object' && !Array.isArray(j)) ? j : {};
  } catch { return {}; }
}

function save(ledger) {
  const days = Object.keys(ledger).sort().slice(-KEEP_DAYS);
  const trimmed = {};
  for (const d of days) trimmed[d] = ledger[d];
  fs.mkdirSync(DATA_DIR(), { recursive: true });
  const tmp = `${LEDGER()}.tmp.${process.pid}`;
  fs.writeFileSync(tmp, JSON.stringify(trimmed, null, 2), 'utf8');
  fs.renameSync(tmp, LEDGER());
}

/** Count one call on a side. Never throws into the caller. */
function record(side, n = 1) {
  const [A, B] = sides();
  if (side !== A && side !== B) return;
  try {
    const l = load();
    const d = today();
    if (!l[d] || typeof l[d] !== 'object') l[d] = { [A]: 0, [B]: 0 };
    l[d][side] = (Number(l[d][side]) || 0) + n;
    save(l);
  } catch { /* a counting failure must never become a call failure */ }
}

function counts() {
  const [A, B] = sides();
  const d = load()[today()] || {};
  return { [A]: Number(d[A]) || 0, [B]: Number(d[B]) || 0 };
}

/** The side the NEXT call should ride to hold the split. Split off → side A (pre-split behavior). */
function pickSide() {
  const [A, B] = sides();
  if (!enabled()) return A;
  const c = counts();
  const total = c[A] + c[B];
  if (!total) return B; // cold start: seed the flat-rate side first
  return (c[B] / total) * 100 < target() ? B : A;
}

function status() {
  const [A, B] = sides();
  const c = counts();
  const total = c[A] + c[B];
  const pct = (n) => total ? Math.round((n / total) * 1000) / 10 : 0;
  return {
    date: today(), enabled: enabled(), sides: [A, B], target_b_pct: target(),
    [A]: c[A], [B]: c[B], total,
    [A + '_pct']: pct(c[A]), [B + '_pct']: pct(c[B]),
    next: pickSide(),
  };
}

module.exports = { enabled, sides, target, record, counts, pickSide, status };

if (require.main === module) console.log(JSON.stringify(status(), null, 2));
